fn parse_command(arg: &str, next_arg: Option<&str>) -> Command {
    if arg == "print-config" || arg == "pc" {
        Command::PrintConfig
    } else if arg == "import-journals" || arg == "imj" {
        Command::ImportJournals { file: PathBuf::from(arg) }
    } else if arg == "assign-priority" || arg == "ap" {
        Command::AssignPriority
    } else if arg == "theme" || arg == "style" {
        // Handle theme/style with subcommand
        if let Some(subcmd) = next_arg {
            match subcmd {
                "print-path" | "path" => Command::Theme(ThemeCommand::PrintPath),
                "print-default" | "default" => Command::Theme(ThemeCommand::PrintDefault),
                "write-defaults" | "write" => Command::Theme(ThemeCommand::WriteDefaults),
                "help" => Command::Theme(ThemeCommand::Help),
                _ => Command::Theme(ThemeCommand::Help),
            }
        } else {
            Command::Theme(ThemeCommand::Help)
        }
    } else if arg == "help" {
        Command::Help
    } else {
        Command::Help
    }
}
```

