#[derive(Debug, Clone, Default)]
struct Config {
    backend_type: String,
    scroll_per_page: u32,
    sync_os_clipboard: bool,
    history_limit: u32,
    colored_tags: bool,
    datum_visibility: String,
    app_state_dir: String,
    export: Export,
    external_editor: ExternalEditor,
    json_backend: JsonBackend,
    sqlite_backend: SqliteBackend,
}

#[derive(Debug, Clone, Default)]
struct Export {
    show_confirmation: bool,
}

#[derive(Debug, Clone, Default)]
struct ExternalEditor {
    auto_save: bool,
    temp_file_extension: String,
}

#[derive(Debug, Clone, Default)]
struct JsonBackend {
    file_path: String,
}

#[derive(Debug, Clone, Default)]
struct SqliteBackend {
    file_path: String,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let cli = parse_args(&args);

    if cli.version {
        print_version();
        return;
    }

    if cli.help {
        print_help();
        return;
    }

    match cli.command {
        Some(Command::PrintConfig) => {
            print_config();
        }
        Some(Command::ImportJournals { file }) => {
            import_journals(&file);
        }
        Some(Command::AssignPriority) => {
            assign_priority();
        }
        Some(Command::Theme(theme_cmd)) => {
            match theme_cmd {
                ThemeCommand::PrintPath => {
                    print_theme_path();
                }
                ThemeCommand::PrintDefault => {
                    print_default_themes();
                }
                ThemeCommand::WriteDefaults => {
                    write_default_themes();
                }
                ThemeCommand::Help => {
                    print_theme_help();
                }
            }
        }
        Some(Command::Help) => {
            print_help();
        }
        None => {
            print_help();
        }
    }
}

fn print_theme_help() {
    println!("Provides commands regarding changing themes and styles of the app");
    println!();
    println!("Usage: {} theme <COMMAND>", APP_NAME);
    println!();
    println!("Commands:");
    println!("  print-path      Prints the path to the user themes file [aliases: path]");
    println!("  print-default   Dumps the styles with the default values to be used as a reference and base for user custom themes [aliases: default]");
    println!("  write-defaults  Creates user custom themes file if doesn't exist then writes the default styles to it [aliases: write]");
    println!("  help            Print this message or the help of the given subcommand(s) [aliases: help]");
    println!();
    println!("Options:");
    println!("  -h, --help  Print help");
}

